    counts = {}
    for r in range(R):
        for c in range(C):
            color = grid[r][c]
            if color != bg_color:
                counts[color] = counts.get(color, 0) + 1

    # Region color is the most frequent non-background color
    if not counts:
        return grid
    region_color = max(counts.items(), key=lambda x: x[1])[0]

    # Find all pixels that belong to neither background nor region
    other_pixels = set()
    for r in range(R):
        for c in range(C):
            if grid[r][c] not in (bg_color, region_color):
                other_pixels.add((r, c))

    # Group these pixels into 8-way connected components
    components = []
    visited = set()
    for r, c in other_pixels:
        if (r, c) not in visited:
            comp = []
            q = [(r, c)]
            visited.add((r, c))
            while q:
                curr_r, curr_c = q.pop(0)
                comp.append((curr_r, curr_c))
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = curr_r + dr, curr_c + dc
                        if (nr, nc) in other_pixels and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
            components.append(comp)

    if not components:
        return grid

    # The stamp is the largest connected component
    stamp_comp = max(components, key=len)

    # Determine the bounding box and center of the stamp
    min_r = min(r for r, c in stamp_comp)
    max_r = max(r for r, c in stamp_comp)
    min_c = min(c for r, c in stamp_comp)
    max_c = max(c for r, c in stamp_comp)

    center_r = (min_r + max_r) // 2
    center_c = (min_c + max_c) // 2

    stamp_pattern = []
    for r, c in stamp_comp:
        stamp_pattern.append((r - center_r, c - center_c, grid[r][c]))

    # Create the output grid as a copy of the input grid
    output_grid = [row[:] for row in grid]

    # Erase the original stamp from the output grid
    for r, c in stamp_comp:
        output_grid[r][c] = bg_color

    # For every other small component (isolated points), apply the stamp
    for comp in components:
        if comp == stamp_comp:
            continue
        # Assuming the isolated point is size 1, representing the center for the stamp
        ir, ic = comp[0]
        for dr, dc, color in stamp_pattern:
            nr, nc = ir + dr, ic + dc
            if 0 <= nr < R and 0 <= nc < C:
                output_grid[nr][nc] = color

    return output_grid
